function validate([n, reservedSeats]) {
  if (!Number.isInteger(n) || n < 1 || n > 1e9) return 'n is between 1 and 10^9.';
  if (!Array.isArray(reservedSeats) || reservedSeats.length < 1 || reservedSeats.length > Math.min(10 * n, 10000)) return 'reservedSeats needs 1 to min(10 * n, 10^4) seats.';
  const seen = new Set();
  for (const pair of reservedSeats) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each reserved seat is a pair [row, seat].';
    const [row, seat] = pair;
    if (!Number.isInteger(row) || row < 1 || row > n) return 'Each row is between 1 and n.';
    if (!Number.isInteger(seat) || seat < 1 || seat > 10) return 'Each seat is between 1 and 10.';
    const key = row * 11 + seat;
    if (seen.has(key)) return 'Reserved seats must be distinct.';
    seen.add(key);
  }
  return null;
}

