function maxNumberOfFamilies(n, reservedSeats) {
  const rows = new Map();
  for (const [row, seat] of reservedSeats) {
    rows.set(row, (rows.get(row) ?? 0) | (1 << seat));
  }

  const left = 0b0000111100;
  const middle = 0b0011110000;
  const right = 0b1111000000;
  let groups = 2 * (n - rows.size);

  for (const mask of rows.values()) {
    const leftFree = (mask & left) === 0;
    const rightFree = (mask & right) === 0;
    if (leftFree && rightFree) {
      groups += 2;
    } else if (leftFree || rightFree || (mask & middle) === 0) {
      groups += 1;
    }
  }
  return groups;
}

