function maxNumberOfFamilies(n, reservedSeats) {
  // For each row that has a reservation, try every set of blocks and keep the largest one that fits.
  const taken = new Set(reservedSeats.map(([r, s]) => r + ':' + s));
  const touched = [...new Set(reservedSeats.map(([r]) => r))];
  const blocks = [[2, 3, 4, 5], [4, 5, 6, 7], [6, 7, 8, 9]];
  let total = 2 * (n - touched.length);
  for (const r of touched) {
    let best = 0;
    for (let pick = 0; pick < 8; pick++) {
      const used = [];
      for (let b = 0; b < 3; b++) if (pick >> b & 1) used.push(...blocks[b]);
      if (new Set(used).size !== used.length) continue;
      if (used.some(s => taken.has(r + ':' + s))) continue;
      best = Math.max(best, used.length / 4);
    }
    total += best;
  }
  return total;
}

