function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const seat = () => (rand() < 0.15 ? (rand() < 0.5 ? 1 : 10) : int(2, 9));
  let n, count, rowPool;
  if (size === 'small') {
    n = rand() < 0.15 ? int(1, 1000000000) : int(1, 5);
    rowPool = Array.from({ length: Math.min(n, 5) }, () => int(1, n));
    count = int(1, Math.min(10 * Math.min(n, 5), 12));
  } else {
    const dense = rand() < 0.5;
    n = dense ? int(400, 1500) : int(1000, 1000000000);
    rowPool = Array.from({ length: dense ? n : int(200, 600) }, (_, i) => (dense ? i + 1 : int(1, n)));
    count = 2000;
  }
  const chosen = new Set(), reservedSeats = [];
  let tries = 0;
  while (reservedSeats.length < count && tries < 100000) {
    tries++;
    const row = rowPool[int(0, rowPool.length - 1)], s = seat(), key = row * 11 + s;
    if (chosen.has(key)) continue;
    chosen.add(key);
    reservedSeats.push([row, s]);
  }
  return [n, reservedSeats];
}
